{"mac":"// Place your key bindings in this file to override the defaultsauto[]
[
    {
        "key": "ctrl+alt+l",
        "command": "sftp.upload.file"
    },
    {
        "key": "alt+cmd+m",
        "command": "explorer.newFolder"
    },
    {
        "key": "cmd+[",
        "command": "editor.fold",
        "when": "editorTextFocus && foldingEnabled"
    },
    {
        "key": "alt+cmd+[",
        "command": "-editor.fold",
        "when": "editorTextFocus && foldingEnabled"
    },
    {
        "key": "cmd+]",
        "command": "editor.unfold",
        "when": "editorTextFocus && foldingEnabled"
    },
    {
        "key": "alt+cmd+]",
        "command": "-editor.unfold",
        "when": "editorTextFocus && foldingEnabled"
    },
    {
        "key": "shift+cmd+g",
        "command": "workbench.view.scm",
        "when": "workbench.scm.active"
    },
    {
        "key": "ctrl+shift+g",
        "command": "-workbench.view.scm",
        "when": "workbench.scm.active"
    },
    {
        "key": "shift+cmd+i",
        "command": "workbench.action.chat.openEditSession",
        "when": "chatEditingParticipantRegistered && !chatSetupHidden && view != 'workbench.panel.chat.view.edits'"
    },
    {
        "key": "shift+cmd+i",
        "command": "-workbench.action.chat.openEditSession",
        "when": "chatEditingParticipantRegistered && !chatSetupHidden && view != 'workbench.panel.chat.view.edits'"
    },
    { "key": "cmd+shift+a",    
      "command": "workbench.action.evenEditorWidths",
      "when": "editorTextFocus" 
    },
    {
        "key": "shift+cmd+m",
        "command": "workbench.action.maximizeEditorHideSidebar",
        "when": "auxiliaryBarVisible || sideBarVisible || editorPartMultipleEditorGroups && !editorPartMaximizedEditorGroup"
    },
    {
        "key": "shift+cmd+,",
        "command": "workbench.action.toggleEditorWidths"
    },
    {
        "key": "ctrl+z ctrl+down",
        "command": "workbench.action.compareEditor.nextChange",
        "when": "textCompareEditorVisible"
    },
    {
        "key": "alt+f5",
        "command": "-workbench.action.compareEditor.nextChange",
        "when": "textCompareEditorVisible"
    },
    {
        "key": "ctrl+z ctrl+up",
        "command": "workbench.action.compareEditor.previousChange",
        "when": "textCompareEditorVisible"
    },
    {
        "key": "shift+alt+f5",
        "command": "-workbench.action.compareEditor.previousChange",
        "when": "textCompareEditorVisible"
    },
    {
        "key": "ctrl+down",
        "command": "cursorMove",
        "args": {
        "to": "down",
        "by": "line",
        "value": 10
        },
        "when": "editorTextFocus"
    },
    {
        "key": "ctrl+up",
        "command": "cursorMove",
        "args": {
        "to": "up",
        "by": "line",
        "value": 10
        },
        "when": "editorTextFocus"
    },
    { 
        "key": "cmd+e",
        "command": "workbench.action.focusActiveEditorGroup",
        "when": "findInputFocussed && editorFocus || replaceInputFocussed && editorFocus"
    },
    {
        "key": "alt+x",
        "command": "editor.action.toggleWordWrap"
    },
    {
        "key": "alt+f",
        "command": "extension.aceJump"
    },
    {
        "key": "alt+d",
        "command": "extension.aceJump.line"
    },
    {
        "key": "alt+s",
        "command": "extension.aceJump.selection"
    }
]"}
